from pathlib import Path
import json
P=Path('work/coastal_pipeline/v4');V=Path('work/coastal_pipeline/v3')
# Freeze shared algorithm; region-specific recipes are manifest inputs.
s=(V/'engine.py').read_text().replace("sys.path.insert(0,'work/coastal_pipeline/v2');from pipeline import preflight","sys.path.insert(0,'work/coastal_pipeline/v4');from preflight import preflight")
s=s.replace("rules=json.loads((HERE/'rules.json').read_text());bs,ds,anchors,issues=preflight(m,rules)","rules=json.loads((HERE/'rules.json').read_text());regional=json.load(open(m['recipes']));rules['recipes']=regional['recipes'];rules['styleZones']=regional.get('styleZones',[]);rules['oceanBeachZones']=regional.get('oceanBeachZones',[]);rules['landmarks']=regional.get('landmarks',{});bs,ds,anchors,issues=preflight(m,rules)")
s=s.replace("Path('outputs/coastal_pipeline_v3')","Path('outputs/coastal_pipeline_v4')").replace("json.load(open(path))['elements']","json.load(gzip.open(path,'rt') if path.endswith('.gz') else open(path))['elements']")
s=s.replace("'recipes':rules['recipes'],'id':m['id']", "'camera':m['camera'],'recipes':rules['recipes'],'id':m['id']")
(P/'engine.py').write_text(s)
s=Path('work/coastal_pipeline/v2/pipeline.py').read_text().replace('import argparse,json,hashlib,csv,sys,subprocess,shutil','import argparse,json,hashlib,csv,sys,subprocess,shutil,gzip')
s=s.replace("def read(path):return json.loads((ROOT/path).read_text())", "def read(path):\n p=ROOT/path\n return json.load(gzip.open(p,'rt') if p.suffix=='.gz' else p.open())")
s=s.replace("d.get('town')==m['id']", "d.get('town') in m.get('towns',[m['id']])")
(P/'preflight.py').write_text(s)
for filename in ['water_wash.py','proof.py']:
 s=(V/filename).read_text().replace('outputs/coastal_pipeline_v3','outputs/coastal_pipeline_v4')
 if filename=='proof.py':
  s=s.replace("cx,cy=meta['center'];cx+=1;span=32", "cx,cy=meta['camera']['center'];span=meta['camera']['desktopSpan']")
  s=s.replace("'MIAMI / exported land edges", "m['id'].upper()+' / exported land edges")
 (P/filename).write_text(s)
r=json.load(open(V/'rules.json'));r.pop('styleZones',None);r.pop('oceanBeachZones',None);r.pop('landmarks',None);r.pop('recipes',None);(P/'rules.json').write_text(json.dumps(r,indent=2))
# Generic application package registry. Approved 30A renderer remains untouched.
p=Path('work/atlas_regions/app.js');s=p.read_text();(P/'app-before-registry.js').write_text(s)
s=s.replace("const towns=catalog.towns", "const packageRegistry=await fetch(assetBase+'package-registry.json').then(r=>r.json());\nconst towns=catalog.towns")
s=s.replace('isMiami','isDetailed');s=s.replace("let detailedLayer=null;const isDetailed=()=>activeTown.id==='miami'&&level!=='state';", "let detailedLayer=null;const detailedLayers=new Map();const isDetailed=()=>!!packageRegistry[activeTown.id]&&level!=='state';")
s=s.replace("if(!detailedLayer){detailedLayer=await createRegionLayer(assetBase+'miami/');scene.add(detailedLayer.root)}", "const packagePath=packageRegistry[activeTown.id];if(detailedLayer)detailedLayer.hide();if(!detailedLayers.has(packagePath)){const layer=await createRegionLayer(assetBase+packagePath);detailedLayers.set(packagePath,layer);scene.add(layer.root)}detailedLayer=detailedLayers.get(packagePath);")
s=s.replace("target.set(detailedLayer.meta.center[0]+1,0,-detailedLayer.meta.center[1]+(innerWidth<700?4:0));span=innerWidth<700?20:32", "const c=detailedLayer.meta.camera||{center:[detailedLayer.meta.center[0]+1,detailedLayer.meta.center[1]],phoneOffsetY:4,phoneSpan:20,desktopSpan:32};target.set(c.center[0],0,-c.center[1]+(innerWidth<700?c.phoneOffsetY:0));span=innerWidth<700?c.phoneSpan:c.desktopSpan")
s=s.replace("districts.find(d=>d.id==='brickell')", "detailedLayer.meta.districts[0]")
s=s.replace("let ds=districts.filter", "let ds=isDetailed()?detailedLayer.meta.districts:districts.filter")
s=s.replace("d=districts.find(d=>d.name===text&&d.town===activeTown.id)", "d=isDetailed()?detailedLayer.meta.districts.find(d=>d.name===text):districts.find(d=>d.name===text&&d.town===activeTown.id)")
s=s.replace("(!isDetailed()||d.town==='miami')", "(!isDetailed()||detailedLayer.meta.districts.some(q=>q.id===d.id))")
s=s.replace("d.town==='30a'||d.town==='miami'", "d.town==='30a'||isDetailed()")
s=s.replace("isDetailed()?'Miami & the bay · regional atlas'", "isDetailed()?activeTown.name+' · regional atlas'")
s=s.replace("Math.hypot(d.x-activeTown.x,d.y-activeTown.y)<24&&(level==='town'||d.town===activeTown.id||(activeTown.id==='southbeach'&&d.town==='miami'))", "(isDetailed()||Math.hypot(d.x-activeTown.x,d.y-activeTown.y)<24&&(level==='town'||d.town===activeTown.id||(activeTown.id==='southbeach'&&d.town==='miami')))")
p.write_text(s)
Path('outputs/florida_coastal_atlas/regions/package-registry.json').write_text(json.dumps({'miami':'miami/'}))
order=['tampa-south-shore','st-pete-clearwater','sarasota-bradenton','naples-marco','fort-myers-sanibel','florida-keys','palm-beaches','fort-lauderdale','treasure-coast','space-coast','daytona-flagler','first-coast','forgotten-coast','nature-coast'];(P/'queue.json').write_text(json.dumps([{'region':x,'status':'pending'} for x in order],indent=2))
